INPUT=$(cat)
CMD=$(echo "$INPUT" | jq -r ".tool_input.command")

if echo "$CMD" | grep -qE "rm -rf|git push.*--force.*main|DROP TABLE"; then
  echo '{"decision": "block", "reason": "Destructive command blocked by policy"}'
